#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Autodev's human-only setup steps (ticket #53). automation/setup.sh does
# everything that can be scripted; run this wizard first, then setup.sh.
# Re-running is safe: each stage checks whether it is already done.

TOTAL_STAGES=5
# Owner and repo come from the dispatcher's config, like setup.sh's.
HERE=$(cd "$(dirname "$0")" && pwd)
config() { python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))[sys.argv[2]])' "$HERE/config.json" "$1"; }
OWNER=$(config owner)
REPO=$(config repo)
ENV_FILE="$HOME/.config/autodev/env"
mkdir -p "$(dirname "$ENV_FILE")" && chmod 700 "$(dirname "$ENV_FILE")"

# The owner's own gh login. GH_TOKEN would override it with the bot's
# token, so it is removed for every command run as the owner.
owner_gh() { env -u GH_TOKEN gh "$@"; }
# GitHub lists a classic token's scopes in the X-OAuth-Scopes header.
scopes_of() { GH_TOKEN="$1" gh api -i user 2>/dev/null | tr -d '\r' | sed -n 's/^[Xx]-[Oo][Aa]uth-[Ss]copes: *//p'; }
has_scope() { [[ ",$(tr -d ' ' <<<"$1")," == *",$2,"* ]]; }

bot_token_works() {
  local token login scopes
  token=$(_existing GH_TOKEN || true)
  [[ -n "$token" ]] || return 1
  login=$(GH_TOKEN="$token" gh api user --jq .login 2>/dev/null) || return 1
  [[ "$login" != "$OWNER" ]] || return 1
  scopes=$(scopes_of "$token" || true)
  has_scope "$scopes" repo && has_scope "$scopes" project
}

banner "Autodev: human-only setup"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Bot account"
if bot_token_works; then
  say "✓ Already done: the bot account $(_existing BOT_LOGIN || true) has a working token."
  pause
else
  say "Autodev acts as its own GitHub account (a \"machine user\"; GitHub allows one"
  say "per person). Its PRs and comments then notify you, and its token can only"
  say "reach this one repo."
  step "Open the signup page in a PRIVATE/incognito window so you stay logged in as $OWNER."
  open_url "https://github.com/signup"
  step "Pick a login, e.g. pokefirered-autodev."
  step "Use a separate email address. Gmail ignores anything after a + so"
  step "  you+autodev@gmail.com reaches your normal inbox but counts as new for GitHub."
  step "Verify the email from the message GitHub sends."
  step "As the bot: Settings → Password and authentication → Enable two-factor"
  step "  authentication (GitHub requires it for accounts that push code)."
  note "Stay logged in as the bot in that private window for the next stage."
  pause "Done creating the bot account?"
fi

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Bot token"
if bot_token_works; then
  say "✓ Already done: the token in $ENV_FILE works and has the repo + project scopes."
  pause
else
  say "A classic personal access token lets the automation act as the bot."
  step "In the private window (logged in as the bot), open the new-token page."
  step "It is prefilled; check that 'repo' and 'project' are both ticked."
  open_url "https://github.com/settings/tokens/new?scopes=repo,project&description=autodev"
  step "Expiration: your choice. When it expires, re-run this wizard to replace it."
  step "Generate token, then copy it (starts ghp_)."
  while :; do
    ask_secret GH_TOKEN "Paste the bot's token:"
    login=$(GH_TOKEN="$GH_TOKEN" gh api user --jq .login 2>/dev/null || true)
    scopes=$(scopes_of "$GH_TOKEN" || true)
    if [[ -z "$login" ]]; then
      warn "GitHub rejected that token. Copy it again."
    elif [[ "$login" == "$OWNER" ]]; then
      warn "That token belongs to $OWNER, not the bot. Create it while logged in as the bot."
    elif ! has_scope "$scopes" repo || ! has_scope "$scopes" project; then
      warn "The token has scopes '$scopes' but needs both repo and project."
    else
      break
    fi
  done
  write_env GH_TOKEN "$GH_TOKEN"
  write_env BOT_LOGIN "$login"
  chmod 600 "$ENV_FILE"
  say "✓ The token belongs to $login, with scopes: $scopes"
  pause
fi

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Your gh login: project scope"
if has_scope "$(owner_gh auth token >/dev/null 2>&1 && scopes_of "$(owner_gh auth token)")" project; then
  say "✓ Already done: your gh login can manage Projects boards."
  pause
else
  say "setup.sh creates the board under your account, so your own gh login"
  say "needs the 'project' scope. gh shows a one-time code and opens GitHub:"
  say "log in there as $OWNER (your normal window), paste the code, approve."
  pause "Ready?"
  owner_gh auth refresh -h github.com -s project || true
  if owner_gh project list --owner "$OWNER" --limit 1 >/dev/null 2>&1; then
    say "✓ gh project list works for $OWNER."
  else
    warn "gh project list still fails; re-run this wizard to try again."
    SKIPPED+=("gh auth refresh -h github.com -s project")
  fi
  pause
fi

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Keep WSL running"
TASK="WSL autodev keepalive"
# conhost.exe --headless runs a console program with no window at all, so
# nothing pops up at logon; wsl.exe -d <distro> --exec sleep infinity keeps
# that distro running for as long as Windows is logged in.
KEEPALIVE_ARGS="--headless wsl.exe -d ${WSL_DISTRO_NAME:-} --exec sleep infinity"
APPDATA_WIN=$(cmd.exe /c 'echo %APPDATA%' 2>/dev/null | tr -d '\r' || true)
if [[ -z "${WSL_DISTRO_NAME:-}" || -z "$APPDATA_WIN" ]]; then
  warn "This doesn't look like WSL with Windows interop, so there's nothing to keep running."
  SKIPPED+=("WSL keepalive (run this wizard inside WSL)")
  pause
  STARTUP_DIR=""
else
  STARTUP_DIR="$(wslpath "$APPDATA_WIN")/Microsoft/Windows/Start Menu/Programs/Startup"
fi
SHORTCUT="$STARTUP_DIR/WSL autodev keepalive.lnk"
if [[ -z "$STARTUP_DIR" ]]; then
  :
elif schtasks.exe /Query /TN "$TASK" >/dev/null 2>&1 || [[ -f "$SHORTCUT" ]]; then
  say "✓ Already done: Windows starts WSL ($WSL_DISTRO_NAME) at logon."
  pause
else
  say "WSL shuts down when no Windows program is using it, which would stop"
  say "the autodev timer. A hidden 'sleep infinity' started at every Windows"
  say "logon keeps it running."
  if confirm "Create the Windows logon task \"$TASK\" now?"; then
    if schtasks.exe /Create /TN "$TASK" /SC ONLOGON /TR "conhost.exe $KEEPALIVE_ARGS" /F >/dev/null 2>&1; then
      say "✓ Created the scheduled task."
    else
      # Logon-triggered tasks usually need an elevated (admin) prompt. A
      # shortcut in your Startup folder does the same job without admin.
      warn "Task Scheduler refused (logon tasks usually need admin)."
      say "Putting a shortcut in your Startup folder instead."
      # PowerShell builds the .lnk file. WindowStyle 7 means "minimised,
      # not focused", a second guard against anything showing at logon.
      # Inside PowerShell's single quotes a ' is written as ''.
      lnk_win=$(wslpath -w "$SHORTCUT"); lnk_win=${lnk_win//\'/\'\'}
      powershell.exe -NoProfile -Command "\$s = (New-Object -ComObject WScript.Shell).CreateShortcut('$lnk_win'); \$s.TargetPath = 'C:\\Windows\\System32\\conhost.exe'; \$s.Arguments = '$KEEPALIVE_ARGS'; \$s.WindowStyle = 7; \$s.Save()" >/dev/null || true
      if [[ -f "$SHORTCUT" ]]; then say "✓ Created $SHORTCUT"
      else warn "Couldn't create the shortcut."; SKIPPED+=("WSL keepalive at Windows logon"); fi
    fi
  else
    SKIPPED+=("WSL keepalive at Windows logon (re-run this wizard)")
  fi
  note "Windows sleep is your call: the automation simply waits while the PC sleeps."
  pause
fi

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Master rulesets (fallback)"
rulesets=$(owner_gh api "repos/$REPO/rulesets" --jq '.[].name' 2>/dev/null || true)
if grep -qx "autodev: master history" <<<"$rulesets" && grep -qx "autodev: master via PR" <<<"$rulesets"; then
  say "✓ Already done: both autodev rulesets exist on master."
  pause
elif ! confirm "Did automation/setup.sh say it could not create the master rulesets?"; then
  say "Nothing to do yet: run automation/setup.sh next. It creates the rulesets"
  say "itself, and tells you to come back here only if GitHub refuses."
  pause
else
  open_url "https://github.com/$REPO/settings/rules"
  say "Create two rulesets (New ruleset → New branch ruleset):"
  step "1) Name 'autodev: master history', Enforcement: Active, no bypass list."
  step "   Target branches → Add target → Include default branch."
  step "   Tick 'Restrict deletions' and 'Block force pushes'. Create."
  step "2) Name 'autodev: master via PR', Enforcement: Active."
  step "   Bypass list → Add bypass → Repository admin (Always allow)."
  step "   Target branches → Include default branch."
  step "   Tick 'Require a pull request before merging' (0 approvals). Create."
  pause "Done creating both?"
fi

finish
say "Next: run automation/setup.sh"
}

run_wizard "$@"; exit
